import numpy as np

def apply_channel(K, rho, sys=None, dim=None):
    '''Applies the channel with Kraus operators in K to the state rho on
    systems specified by the list sys. The dimensions of the subsystems of
    rho are given by dim.
    Inputs:
    K: list of 2d array of floats, list of Kraus operators
    rho: 2d array of floats, input density matrix
    sys: list of int or None, list of subsystems to apply the channel, None means full system
    dim: list of int or None, list of dimensions of each subsystem, None means full system
    Output:
    matrix: output density matrix of floats
    '''
    if sys is None:
        return sum(np.kron(K_i, np.conj(K_i).T) @ rho for K_i in K)

    if dim is None:
        dim = [rho.shape[0] // (len(sys) * np.prod([d for d in sys])) for _ in range(len(sys))]

    output_rho = np.zeros_like(rho)
    for i, K_i in enumerate(K):
        if sys is not None:
            identity_parts = []
            for j, d in enumerate(dim):
                if j!= i:
                    identity_parts.append(np.eye(d))
                else:
                    break
            for j, d in enumerate(dim):
                if j!= i:
                    identity_parts.append(np.eye(d))
            identity = tensor(*identity_parts)
        else:
            identity = np.eye(rho.shape[0])

        if sys is not None:
            Kraus_i = K_i.reshape((K_i.shape[0] // dim[i], dim[i], K_i.shape[1] // dim[i], dim[i]))
            Kraus_i = Kraus_i.transpose(0, 2, 1, 3).reshape((K_i.shape[0] * dim[i], K_i.shape[1] * dim[i]))
            rho_i = rho.reshape((rho.shape[0] // (len(sys) * dim[i]), len(sys) * dim[i], rho.shape[1] // (len(sys) * dim[i]), len(sys) * dim[i]))
            rho_i = rho_i.transpose(0, 2, 1, 3).reshape((rho.shape[0] * (len(sys) * dim[i]), len(sys) * dim[i]))
            output_rho += np.kron(identity, np.kron(Kraus_i, np.conj(Kraus_i).T)) @ rho_i
        else:
            output_rho += np.kron(identity, np.kron(K_i, np.conj(K_i).T)) @ rho

    return output_rho
