import numpy as np

def Bspline(xi, i, p, Xi):
    if p == 0:
        if Xi[i] <= xi < Xi[i+1]:
            return 1.0
        else:
            return 0.0
    else:
        alpha = (xi - Xi[i]) / (Xi[i + p] - Xi[i])
        beta = (Xi[i + p + 1] - xi) / (Xi[i + p + 1] - Xi[i + 1])
        return alpha * Bspline(xi, i, p - 1, Xi) + beta * Bspline(xi, i + 1, p - 1, Xi)
