def Rlnm(l, n, m, k, z, N_t):
    '''Function to calculate the translation coefficient (R|R)lmn.
    Input
    l : int
        The principal quantum number for the expansion.
    n : int
        The principal quantum number for the reexpansion.
    m : int
        The magnetic quantum number for the reexpansion.
    k : float
        Wavevector of the optical beam.
    z : float
        The translation distance along z direction
    N_t : int
        Truncated space size.
    Output
    (R|R)lmn : complex
        The translation coefficient (R|R)lmn.
    '''
    # Initialization
    (R|R)lmn = 0
    if l == 0 and n == 0 and m == 0:
        (R|R)lmn = (-1)**l * np.sqrt(2*l + 1) * scipy.special.sph_jn(l, k*z)

    # Recursion for other cases
    if l > 0:
        if l == n + 1:
            (R|R)lmn = (scipy.special.sph_jn(l-1, k*z) - scipy.special.sph_jn(l+1, k*z)) / (b_l_m(l-1, m, n) - b_l_m(l+1, m, n))
        else:
            (R|R)lmn = (a_l_m(l+1, n, m, l, n) * scipy.special.sph_jn(l+1, k*z) - a_l_m(l-1, n, m, l, n) * scipy.special.sph_jn(l-1, k*z)) / (a_l_m(l+1, n, m, l, n) - a_l_m(l-1, n, m, l, n))

    return (R|R)lmn

def a_l_m(n, m, l, n, m):
    '''Helper function to calculate coefficient a_l_m'''
    if n >= abs(m):
        return np.sqrt((n+1+abs(m))*(n+1-abs(m)) / ((2*n+1)*(2*n+3)))
    return 0

def b_l_m(n, m, l):
    '''Helper function to calculate coefficient b_l_m'''
    if 0 <= m <= n:
        if n >= abs(m):
            return np.sqrt((n-m-1)*(n-m) / ((2*n-1)*(2*n+1)))
    elif -n <= m < 0:
        if n >= abs(m):
            return -np.sqrt((n-m-1)*(n-m) / ((2*n-1)*(2*n+1)))
    return 0
